register_both:
import {AuthConfig, SdkConfig, buildClient, registerInstances} from '@webcommander/webcommander';

registerInstances([
    new SdkConfig(
        new AuthConfig({
            clientName: 'default',
            baseUrl: process.env.WC_BASE_URL,
            clientId: process.env.WC_CLIENT_ID,
            clientSecret: process.env.WC_CLIENT_SECRET,
            authBaseUrl: process.env.WC_AUTH_BASE_URL,
        }),
        {raiseOnError: true},
    ),
    new SdkConfig(
        new AuthConfig({
            clientName: 'legacy',
            grantType: 'client_credentials',
            baseUrl: process.env.WC_LEGACY_BASE_URL,
            clientId: process.env.WC_LEGACY_CLIENT_ID,
            clientSecret: process.env.WC_LEGACY_CLIENT_SECRET,
            redirectUri: process.env.WC_LEGACY_REDIRECT_URI,
            authString: process.env.WC_LEGACY_AUTH_STRING,
        }),
        {raiseOnError: true},
    ),
]);

const client = await buildClient();
const legacyClient = await buildClient('legacy');
